  virtual std::shared_future<ccxt::any>
  fetchTransactionsWithMethod(ccxt::any method, ccxt::any code = ccxt::any{},
                              ccxt::any since = ccxt::any{},
                              ccxt::any limit = ccxt::any{},
                              ccxt::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any request = ccxt::dict{};
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("limit"), limit);
                 }
                 if (isTrue(!isEqual(since, ccxt::any{}))) {
                   ::setValue(request, std::string("after"), since);
                 }
                 ccxt::any currency = ccxt::any{};
                 if (isTrue(!isEqual(code, ccxt::any{}))) {
                   currency = this->currency(code);
                 }
                 ccxt::any response = ccxt::any{};
                 if (isTrue(
                         isEqual(method, std::string("privateGetTransfers")))) {
                   response = awaitValue(this->privateGetTransfers(
                       this->extend(request, params)));
                 } else if (isTrue(isEqual(
                                method, std::string("privateGetDeposits")))) {
                   response = awaitValue(
                       this->privateGetDeposits(this->extend(request, params)));
                 } else {
                   response = awaitValue(this->privateGetWithdrawals(
                       this->extend(request, params)));
                 }
                 return this->parseTransactions(response, currency, since,
                                                limit);
               })
        .share();
  }

